 "content": "from collections import Counter


def transform(grid):
    """Fill zeroed cells in a cyclic 1..9 row pattern, preserving visible marks."""
    h, w = len(grid), len(grid[0])
    # Every ordinary row follows the same cyclic sequence across columns.
    # Count phase estimates from visible cells; diagonal marks and other
    # irregular cells are sparse compared with the background pattern.
    phases = []
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                phases.append(((value - 1 - c) % 9))
    phase = Counter(phases).most_common(1)[0][0]
    out = [list(row) for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                out[r][c] = (phase + c) % 9 + 1
    return out
